#!/usr/bin/env python3
# PATH: fix167.py
# GOLDEN SEED -- fix167: folder page review pass (ticks, money, popups, links, dead code) + fresh seed data v4.
#
#   1. STAGE TICKS: ticks made on New Project now arrive on the folder page (JSON name bug: isCompleted was read
#      as "completed"). Ticks are orange in view mode too; hovering shows when and by whom. New Project uses the
#      app's own JSON reader (dates + stage list work) and sends no stages for New Title / Legacy Title.
#   2. Same JSON bug fixed for isReleased and isLegacy: hand-over and LEGACY now show everywhere, and EDIT + SAVE
#      no longer wipes the legacy flag.
#   3. STORAGE FEES: a pause really skips the paused days; rate 0 = no fee (it silently became 50,000); RESUME needs
#      a reason; the 8 old reason-less endpoints are deleted; set-aside fees stay visible and block the hand-over;
#      the 365-day auto move keeps set-aside fees and restarts the month count.
#   4. PAYMENTS: each payment records WHICH owner paid (required for joint owners) and if it is for the TITLE or
#      STORAGE fees; storage fees paid / unpaid are shown; the receipt opens from Payment History.
#   5. PROBLEM / HAND-OVER: problem flag stores who, when and why (shown on the page and on Recovery cards); two
#      clicks can no longer cancel each other; hand-over needs a note (who collected it); system notes are locked.
#   6. POPUPS: errors show inside the popup in RED, no duplicate toast, a confirm on top of a popup no longer blurs
#      it, no CANCEL next to the X, every button has a hover explanation.
#   7. LINKS + DESIGN: Related Projects open the right folder (they went to a missing page), deleted projects are
#      left out and show a DELETED banner; RELEASED is cyan in the Ledger; CRITICAL shows in the folder header.
#   8. DEAD CODE: 2 .bak files, ~270 unused / duplicate CSS rules, unused service calls and old links removed.
#   9. SEED DATA v4: deletes ALL old seed data (v1, v2, v3) and loads 118 projects, every situation TWICE.
#  10. LLM_CONTEXT_GUIDE.md: storage-fee rules, fix167 summary and seed v4 updated.
#
# NOT in this fix: per-owner SHARES of a joint project's cost/fees (fees stay per project; who agreed and who paid
# are recorded), adding/removing a joint owner on the folder page, real call logs (backbone step 4), history tab (step 6).
#
# Atomic: every patch for every file is matched in memory first; if any one is
# MISSING nothing is written and nothing is committed. Runs the backend compile
# (mvnw / mvn) and `npm run build` before committing when they are available,
# and puts every file back exactly as it was if either goes red.
