        '        "KATO", "NAMULI", "OKELLO", "NAKATO", "MUWANGA", "BIRUNGI", "KYOMUHENDO", "ATIM", "WAISWA", "TUSIIME",',
        '        "MATOVU", "OKWIR", "WANDERA", "OKURUT", "TWINOMUJUNI", "MUKASA", "KIRABO", "NAIGA", "MBABAZI", "NALWEYISO",',
