        '        {"KAMPALA", "KYADONDO", "KAWEMPE DIVISION", "MAKERERE III", "KIKONI"},',
        '        {"LUWEERO", "KATIKAMU", "LUWEERO TOWN COUNCIL", "BAMUNANIKA", "WOBULENZI"},',
        '        {"KABAROLE", "BURAHYA", "FORT PORTAL CITY EAST DIVISION", "KARAMBI", "KISIMBA"},',
