        '        background: #f9f9f9 !important;',
        '        border: 1px solid #cccccc !important;',
        '        border-radius: 0 !important;',
        '        padding: 8px 10px !important;',
        '        page-break-inside: avoid !important;',
        '        break-inside: avoid !important;',
        '    }',
        '',
        '    .ownerName {',
        "        font-family: 'Arial Black', Arial, sans-serif !important;",
        '        font-size: 11pt !important;',
        '        font-weight: 900 !important;',
        '        color: #000000 !important;',
        '        border-bottom: 1px solid #dddddd !important;',
        '        padding-bottom: 4px !important;',
        '        margin-bottom: 5px !important;',
        '    }',
        '',
        '    .infoRow {',
        '        color: #333333 !important;',
        '        font-size: 9pt !important;',
        '        margin-bottom: 3px !important;',
        '        display: flex !important;',
        '        align-items: flex-start !important;',
        '        gap: 6px !important;',
        '    }',
        '',
        '    .infoRow svg { color: #000000 !important; flex-shrink: 0 !important; }',
        "    .phoneHighlight { font-family: 'Courier New', monospace !important; color: #000000 !important; font-size: 10pt !important; font-weight: 700 !important; }",
        '',
        '    /* \u2500\u2500 NOTES \u2500\u2500 */',
        '    .notebookTimeline {',
        '        max-height: none !important;',
        '        overflow: visible !important;',
        '        display: flex !important;',
        '        flex-direction: column !important;',
        '        gap: 6px !important;',
        '    }',
        '',
        '    .ruledNote {',
        '        background: #ffffff !important;',
        '        border: 1px solid #cccccc !important;',
        '        border-left: 3px solid #000000 !important;',
        '        box-shadow: none !important;',
        '        padding: 6px 10px !important;',
        '        page-break-inside: avoid !important;',
        '        break-inside: avoid !important;',
        '    }',
        '',
        '    .noteContent { color: #000000 !important; font-size: 9pt !important; line-height: 1.5 !important; }',
        '    .noteTime    { color: #555555 !important; font-size: 8pt !important; }',
        '    .noteAuthor  { color: #777777 !important; font-size: 8pt !important; }',
        '',
        '    .noteMeta {',
        '        display: flex !important;',
        '        justify-content: space-between !important;',
        '        border-bottom: 1px solid #eeeeee !important;',
        '        padding-bottom: 3px !important;',
        '        margin-bottom: 4px !important;',
        '    }',
        '',
        '    /* \u2500\u2500 DOCUMENTS \u2500\u2500 */',
        '    .compactVault {',
        '        max-height: none !important;',
        '        overflow: visible !important;',
        '        background: #f9f9f9 !important;',
        '        border: 1px solid #dddddd !important;',
        '        padding: 8px 10px !important;',
        '        display: flex !important;',
        '        flex-direction: column !important;',
        '        gap: 4px !important;',
        '    }',
        '',
        '    .docTag {',
        '        background: #f0f0f0 !important;',
        '        border: 1px solid #cccccc !important;',
        '        border-radius: 0 !important;',
        '        padding: 4px 8px !important;',
        '        display: flex !important;',
        '        align-items: center !important;',
        '        gap: 6px !important;',
        '        page-break-inside: avoid !important;',
        '    }',
        '',
        '    .docName { color: #000000 !important; font-size: 9pt !important; font-weight: 700 !important; text-decoration: none !important; }',
        '    .docIcon { color: #000000 !important; }',
        '',
        '    /* \u2500\u2500 EMPTY STATES \u2014 hide on print \u2500\u2500 */',
        '    .emptyState { display: none !important; }',
        '',
        '    /* \u2500\u2500 PRINT FOOTER \u2500\u2500 */',
        '    @page {',
        '        @bottom-center {',
        '            content: "GE SOLUTIONS \u2014 LAND REGISTRY DIVISION  |  CONFIDENTIAL  |  Page " counter(page) " of " counter(pages);',
        '            font-family: Arial, sans-serif;',
        '            font-size: 7pt;',
        '            color: #888888;',
        '        }',
        '    }',
        '',
        '    body {',
        '        -webkit-print-color-adjust: exact;',
        '        print-color-adjust: exact;',
        '    }',
        '}',
        '',
        '/* Folder redesign tokens */',
        '',
        '.badgeBacklog{background:#7c2d12;color:#fff;border-radius:4px;padding:2px 8px;font-size:11px;margin-right:6px}',
        '.badgeRecv{background:#b91c1c;color:#fff;border-radius:4px;padding:2px 8px;font-size:11px}',
        '',
        '.btnPrimary{background:#f97316;color:#fff;border:none;border-radius:6px;padding:8px 12px;cursor:pointer}',
        '',
        '.btnDanger{background:#b91c1c;color:#fff;border:none;border-radius:6px;padding:8px 12px;cursor:pointer}',
        '',
        '/* FS-UNIFY v1 \u2014 tokens + classes ported from Intake/Ledger reference */',
        ':root{--fs-orange:#EE8C3A;--fs-red:#ef4444;--fs-green:#34d399;--fs-muted:rgba(255,255,255,.6);--fs-line:rgba(255,255,255,.08);}',
        ".textBadge{font-family:'Space Mono',monospace;font-size:10px;font-weight:900;letter-spacing:1.5px;text-transform:uppercase;padding:2px 0;border-bottom:1px solid currentColor;background:none}",
        '.badgeBacklog{color:var(--fs-orange)}',
        '.badgeRecv{color:var(--fs-red)}',
        '.badgeTitled{color:var(--fs-green)}',
        '.badgeActive{color:var(--fs-muted)}',
        '',
        ".portfolioTable{width:100%;border-collapse:collapse;font-family:'Space Mono',monospace;font-size:12px}",
        '.portfolioTable th{text-align:left;font-size:10px;letter-spacing:1.5px;color:var(--fs-muted);border-bottom:1px solid var(--fs-line);padding:6px 8px}',
        '.portfolioTable td{padding:7px 8px;border-bottom:1px solid var(--fs-line)}',
        '.portfolioTable tbody tr:hover td{background:rgba(255,255,255,.03);cursor:pointer}',
        '',
        '.iconBtnDanger{background:transparent;border:none;color:var(--fs-red);cursor:pointer;font-size:15px;padding:4px}',
        '',
        '.convertRow{display:flex;align-items:center;gap:10px;margin:0 0 12px}',
        '',
        '.ghostBtn{background:transparent;border:1px solid rgba(255,255,255,.25);color:rgba(255,255,255,.8);border-radius:6px;padding:8px 12px;cursor:pointer;font-weight:900;font-size:11px}',
        '',
        '.recvActionRow{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}',
        '.printStatement{display:none}',
        "@media print{.printStatement{display:block;font-family:'Space Mono',monospace;font-size:11px;color:#000;margin:12px 0}",
        '.printStatement table{width:100%;border-collapse:collapse}',
        '.printStatement td,.printStatement th{border-bottom:1px solid #ccc;padding:4px 6px;text-align:left}}',
        '',
        '.drawerHeader{border-bottom:1px solid rgba(238,140,58,.55);}',
        ".drawerTitle{font-family:'Cinzel',serif;color:var(--fs-orange);letter-spacing:.08em;text-transform:uppercase;font-weight:700;}",
        '.drawerIcon{color:var(--fs-orange);}',
        '.chevron{color:var(--fs-orange);}',
        '',
        ".specValue{color:var(--fs-orange);font-family:'Space Mono',monospace;}",
        '.hwInput{background:#fff;color:#122a28;border:1.5px solid #c8d6d7;border-radius:8px;}',
        '',
        '.selectTrigger{background:#fff;color:#122a28;border:1.5px solid #c8d6d7;border-radius:8px;}',
        '',
        '.reqStar{color:var(--fs-orange);}',
        '.currencyTag{color:var(--fs-orange);}',
        '',
        '.ctrlBtnPay{background:#20403c;color:#fff;border:1px solid rgba(255,255,255,.18);}',
        '.unlockMasterBtn{background:var(--fs-orange);color:#1a2e30;}',
        '.panelInner{background:transparent;}',
        '',
        '/* FS-UNIFY v3 \u2014 tokens ported verbatim from IntakePage.module.css at runtime */',
        ':root{--fs-orange:#EE8C3A;--fs-green:#10b981;--fs-red:#ef4444;--fs-cream:#fff;--fs-dark:#122a28;--fs-muted:rgba(255,255,255,.6);--fs-line:rgba(255,255,255,.08);}',
        '.drawerHeader{border-bottom:1px solid #EE8C3A;}',
        ".drawerTitle{font-family:'Cinzel',serif;color:#EE8C3A;letter-spacing:.08em;text-transform:uppercase;font-weight:700;}",
        '.drawerIcon,.chevron{color:#EE8C3A;}',
        '.specLabel{color:var(--fs-muted);letter-spacing:1.5px;text-transform:uppercase;}',
        ".specValue{color:#EE8C3A;font-family:'Space Mono',monospace;}",
        '.hwInput,.selectTrigger{background:#fff;color:#122a28;border:1.5px solid #c8d6d7;border-radius:8px;}',
        '',
        '.selectValue{color:#122a28;}',
        '.inputLabelRow label{color:rgba(255,255,255,.85);letter-spacing:1.2px;text-transform:uppercase;font-size:10px;font-weight:700;}',
        '.reqStar,.currencyTag{color:#EE8C3A;}',
        '',
        '.ctrlBtnPay{background:#1a2e30;color:#fff;border:1px solid rgba(255,255,255,.18);}',
        '.unlockMasterBtn{background:#EE8C3A;color:#1a2e30;}',
        '.btnPrimary{background:#EE8C3A;color:#1a2e30;}',
        '.btnDanger{background:transparent;color:#ef4444;border:1.5px solid #ef4444;}',
        '',
        '/* FS-UNIFY v4 \u2014 EXACT Intake port (values verbatim from IntakePage.module.css) */',
        '.container{',
        '  --orange:#EE8C3A; --orange-dim:rgba(238,140,58,0.18); --orange-border:rgba(238,140,58,0.28);',
        '  --navy:#213E40; --navy-deep:#1a2e30; --red:#ef4444; --green:#10b981;',
        '  --gap-xl:clamp(10px,1.6vw,18px); --gap-lg:clamp(7px,1.1vw,14px); --gap-md:clamp(5px,0.9vw,10px);',
        '  --radius:10px; --radius-sm:6px;',
        '  --fs-h1:clamp(18px,2.5vw,24px); --fs-sub:clamp(9px,0.9vw,11px); --fs-label:clamp(8px,0.85vw,10px);',
        '  --fs-value:clamp(10px,1.05vw,12px); --fs-meta:clamp(8px,0.85vw,10px); --fs-btn:clamp(8px,0.85vw,10px);',
        '  --input-height:clamp(34px,4.3vw,40px); --input-font:clamp(11px,1.05vw,13px);',
        '  --input-px:clamp(9px,1.2vw,13px); --input-radius:6px;',
        "  font-family:'Inter',sans-serif;",
        '}',
        '/* Panel shell: orange hairline border + bottom corner brackets + 4 dots (Intake decor) */',
        '.hwPanel{',
        '  border:1px solid var(--orange-border); border-radius:var(--radius); position:relative;',
        '  background-image:',
        '    radial-gradient(circle,var(--orange) 1.3px,transparent 1.8px),',
        '    radial-gradient(circle,var(--orange) 1.3px,transparent 1.8px),',
        '    radial-gradient(circle,var(--orange) 1.3px,transparent 1.8px),',
        '    radial-gradient(circle,var(--orange) 1.3px,transparent 1.8px),',
        '    linear-gradient(160deg,#1c3335 0%,#213E40 100%);',
        '  background-position:calc(50% - 15px) calc(100% - 8px),calc(50% - 5px) calc(100% - 8px),calc(50% + 5px) calc(100% - 8px),calc(50% + 15px) calc(100% - 8px),0 0;',
        '  background-size:4px 4px,4px 4px,4px 4px,4px 4px,auto;',
        '  background-repeat:no-repeat;',
        '}',
        ".hwPanel::before,.hwPanel::after{content:'';position:absolute;bottom:6px;width:14px;height:14px;border-bottom:2px solid var(--orange);pointer-events:none;}",
        '.hwPanel::before{left:8px;border-left:2px solid var(--orange);}',
        '.hwPanel::after{right:8px;border-right:2px solid var(--orange);}',
        '.drawerHeader{background:rgba(0,0,0,0.22);border-bottom:1px solid var(--orange);border-radius:calc(var(--radius) - 1px) calc(var(--radius) - 1px) 0 0;padding:clamp(8px,1.2vw,14px) clamp(10px,1.6vw,18px);}',
        ".drawerTitle{font-family:'Cinzel',serif;color:var(--orange);font-size:clamp(11px,1.3vw,14px);font-weight:700;letter-spacing:2px;text-transform:uppercase;}",
        '.drawerIcon,.chevron{color:var(--orange);}',
        '.panelInner{background:rgba(255,255,255,0.05);}',
        '/* Labels = Intake .label */',
        ".inputLabelRow label,.specLabel{font-family:'Inter',sans-serif;font-size:var(--fs-label);font-weight:900;color:rgba(255,255,255,0.5);text-transform:uppercase;letter-spacing:2px;}",
        '.reqStar{color:var(--red);}',
        '.inputHint{font-size:var(--fs-meta);font-weight:700;color:rgba(255,255,255,0.35);letter-spacing:0.5px;}',
        '/* Read-only values = Intake .indexDisplay */',
        ".specValue{font-family:'Space Mono',monospace;font-weight:900;letter-spacing:1px;color:var(--orange);font-size:var(--input-font);}",
        '.specItem{border-left:2px solid rgba(238,140,58,0.35);padding:3px 0 3px 8px;}',
        '/* Editable inputs = Intake .input */',
        '.hwInput, .selectTrigger {',
        "  font-family:'Inter',sans-serif;font-weight:600;border:1.5px solid rgba(238,140,58,0.3);",
        '  background:#ffffff;color:var(--navy);border-radius:var(--input-radius);',
        '  height:var(--input-height);padding:0 var(--input-px);font-size:var(--input-font);',
        '  transition:border-color .2s,box-shadow .2s;width:100%;box-sizing:border-box;',
        '}',
        '.hwInput:hover, .selectTrigger:hover {border-color:var(--orange);}',
        '.hwInput:focus, .selectTrigger:focus {outline:none;border-color:var(--orange);box-shadow:0 0 0 2px rgba(238,140,58,0.15);}',
        '.hwInput::placeholder{color:#9aa8a6;}',
        '.selectValue{color:var(--navy);}',
        '/* Secondary/toggle buttons = Intake .typeBtn / .addBtn */',
        '.payTypeBtn, .ghostBtn, .addNoteBtn, .addDocBtn {',
        "  font-family:'Inter',sans-serif;font-weight:900;font-size:var(--fs-btn);letter-spacing:1.5px;text-transform:uppercase;",
        '  background:rgba(26,46,48,0.75);border:1.5px solid rgba(255,255,255,0.18);color:rgba(255,255,255,0.85);',
        '  border-radius:6px;padding:clamp(6px,0.9vw,9px) clamp(10px,1.4vw,16px);',
        '}',
        '.payTypeBtn:hover, .ghostBtn:hover, .addNoteBtn:hover, .addDocBtn:hover {background:rgba(238,140,58,0.12);color:#EE8C3A;border-color:#EE8C3A;}',
        '.payTypeBtnActive, .payTypeBtnActive:hover {background:#EE8C3A;color:#1a2e30;border-color:#EE8C3A;box-shadow:0 0 14px rgba(238,140,58,0.4);}',
        '',
        '/* Primary buttons = Intake .btn.primary (WHITE text on orange) */',
        ".unlockMasterBtn,.btnPrimary{background:var(--orange);color:#fff;border-color:var(--orange);font-family:'Inter',sans-serif;font-weight:900;font-size:var(--fs-btn);letter-spacing:1.5px;}",
        '.unlockMasterBtn:hover,.btnPrimary:hover{background:#d97a2b;border-color:#d97a2b;color:#fff;}',
        ".btnDanger {background:rgba(239,68,68,0.08);color:var(--red);border:1.5px solid rgba(239,68,68,0.45);font-family:'Inter',sans-serif;font-weight:900;font-size:var(--fs-btn);letter-spacing:1.5px;}",
        '.btnDanger:hover{background:rgba(239,68,68,0.16);border-color:var(--red);color:var(--red);}',
        '',
        ".btn, .ctrlBtnPay, .purgeBtn, .printBtn {font-family:'Inter',sans-serif;}",
        '/* Stage rows = Intake .stageItem */',
        '',
        '/* Money boxes = Intake .financialsSummary */',
        '.statBox{background:rgba(0,0,0,0.15);border:1px solid rgba(255,255,255,0.06);border-radius:var(--radius-sm);padding:var(--gap-lg);}',
        ".statBox label{font-family:'Inter',sans-serif;font-size:var(--fs-label);font-weight:900;color:rgba(255,255,255,0.5);letter-spacing:2px;text-transform:uppercase;}",
        ".statBox strong{font-family:'Space Mono',monospace;font-size:var(--input-font);color:var(--orange);letter-spacing:1px;}",
        '/* Portfolio table + headings = Intake tones */',
        '',
        ".portfolioTable{font-family:'Space Mono',monospace;font-size:var(--fs-value);}",
        ".portfolioTable th{font-family:'Inter',sans-serif;font-size:var(--fs-label);font-weight:900;color:rgba(255,255,255,0.5);letter-spacing:2px;border-bottom:1px solid rgba(255,255,255,0.06);}",
        '.portfolioTable td{border-bottom:1px solid rgba(255,255,255,0.06);color:rgba(255,255,255,0.85);}',
        '.textBadge{font-size:var(--fs-meta);font-weight:700;letter-spacing:1px;}',
        ".emptyState span{font-family:'Inter',sans-serif;font-size:var(--fs-meta);font-weight:700;color:rgba(255,255,255,0.35);letter-spacing:0.5px;}",
        '',
        '/* FS-UNIFY v5 \u2014 exact CollapsibleSection/Intake parity */',
        '.container{--btn-height:clamp(32px,4vw,38px);--btn-px:clamp(10px,1.4vw,16px);--btn-font:clamp(8px,0.85vw,10px);--input-radius:6px;}',
        '.hwPanel{',
        '  background:linear-gradient(135deg,#3a5a5c 0%,#2a4a4c 50%,#213E40 100%);',
        '  border:1px solid rgba(238,140,58,0.2);border-radius:10px;',
        '  box-shadow:0 6px 24px rgba(0,0,0,0.25);',
        '  transition:border-color .3s ease,box-shadow .3s ease;',
        '}',
        '.hwPanel:hover{border-color:#EE8C3A;box-shadow:0 8px 32px rgba(0,0,0,0.3);}',
        '.hwPanel::before,.hwPanel::after{content:none;}',
        '.drawerHeader{background:#162a2c;border-bottom:1.5px solid transparent;border-radius:9px 9px 0 0;padding:clamp(8px,1.1vw,12px) clamp(10px,1.4vw,16px);}',
        '.drawerHeader[aria-expanded="true"]{border-bottom-color:#EE8C3A;}',
        ".drawerTitle{font-family:'Cinzel',serif;font-size:clamp(10px,1.3vw,13px);font-weight:700;color:#EE8C3A;letter-spacing:2px;text-transform:uppercase;}",
        '.drawerHeader:hover .drawerTitle{color:#fff;}',
        '.drawerIcon{color:#EE8C3A;filter:drop-shadow(0 0 4px rgba(238,140,58,0.4));font-size:clamp(12px,1.4vw,16px);}',
        '.chevron{color:rgba(255,255,255,0.4);font-size:14px;}',
        '.chevron.rotated{color:#EE8C3A;}',
        '.panelInner{position:relative;background:transparent;padding:clamp(10px,1.4vw,16px);display:flex;flex-direction:column;gap:clamp(7px,1.1vw,14px);}',
        '.specItem{border-left:none;padding:0;}',
        '.currencyTag,.autoCalcBadge{background:none;border:none;box-shadow:none;color:rgba(255,255,255,0.35);font-size:var(--fs-meta);font-weight:700;letter-spacing:0.5px;padding:0;text-transform:uppercase;}',
        '.drawerCount{background:none;border:none;color:rgba(255,255,255,0.4);font-size:var(--fs-meta);padding:0;}',
        '.idPlate h1{font-size:var(--fs-h1);letter-spacing:2px;}',
        '',
        '.unlockMasterBtn,.btnPrimary{box-shadow:0 4px 12px rgba(238,140,58,0.3);}',
        '.unlockMasterBtn:hover,.btnPrimary:hover{background:#d97a2b;border-color:#d97a2b;color:#fff;box-shadow:0 4px 12px rgba(238,140,58,0.3);}',
        '',
        '/* FS-UNIFY v6 \u2014 feedback pass */',
        '.bodyOpen{overflow:visible;}',
        '.capsBadge{background:none;border:none;box-shadow:none;border-radius:0;color:rgba(255,255,255,0.35);font-size:8px;font-weight:700;letter-spacing:0.5px;padding:0;}',
        ".convertBtn{display:flex;align-items:center;gap:5px;background:rgba(26,46,48,0.75);border:1.5px solid rgba(255,255,255,0.18);color:rgba(255,255,255,0.85);padding:clamp(6px,0.9vw,9px) clamp(10px,1.4vw,16px);border-radius:6px;font-family:'Inter',sans-serif;font-weight:900;font-size:var(--fs-btn);letter-spacing:1.5px;text-transform:uppercase;cursor:pointer;transition:all .2s ease;white-space:nowrap;}",
        '.convertBtn:hover{background:rgba(238,140,58,0.12);color:#EE8C3A;border-color:#EE8C3A;}',
        '.convertBtnActive,.convertBtnActive:hover{background:#EE8C3A;color:#1a2e30;border-color:#EE8C3A;box-shadow:0 0 14px rgba(238,140,58,0.4);}',
        '.badgeActive{color:#213E40;}',
        '.badgeLegacy{color:#64748b;}',
        '.selectValue{font-size:var(--input-font);font-weight:600;}',
        '.selectDropdown{position:absolute;z-index:600;margin-top:4px;max-height:240px;overflow:auto;background:#ffffff;border:1.5px solid rgba(238,140,58,0.3);border-radius:6px;box-shadow:0 8px 24px rgba(0,0,0,0.25);list-style:none;padding:0;}',
        ".selectOption{color:#213E40;font-family:'Inter',sans-serif;font-weight:600;font-size:var(--input-font);padding:8px var(--input-px);cursor:pointer;}",
        '.selectOption:hover{background:rgba(238,140,58,0.12);}',
        '.selectOptionActive,.selectOptionActive:hover{background:#EE8C3A;color:#1a2e30;}',
        '',
        '/* FS-UNIFY v7 \u2014 tokens fix, curved bottoms, badge chips, red owed, X anim */',
        '.container{--fs-green:#10b981;--fs-red:#ef4444;}',
        '',
        '.drawerHeader[aria-expanded="false"]{border-radius:9px;}',
        '.statRed label,.statRed strong{color:var(--fs-red) !important;}',
        ".textBadge{background:rgba(238,140,58,0.10);border:1px solid rgba(238,140,58,0.35);border-radius:999px;padding:3px 9px;font-family:'Inter',sans-serif;}",
        '',
        '.badgeRecv{color:#ef4444;background:rgba(239,68,68,0.10);border-color:rgba(239,68,68,0.35);}',
        '.badgeActive{color:#213E40;background:rgba(33,62,64,0.10);border-color:rgba(33,62,64,0.35);}',
        '',
        '.badgePaused{color:#06b6d4;background:rgba(6,182,212,0.10);border-color:rgba(6,182,212,0.35);}',
        '',
        '@keyframes xPop{from{transform:rotate(0)}to{transform:rotate(90deg)}}',
        '',
        '/* FS-UNIFY v8 \u2014 attention-color semantics */',
        '.badgeActive{color:#10b981;background:rgba(16,185,129,0.10);border-color:rgba(16,185,129,0.35);}',
        '.badgeTitled{color:#10b981;background:rgba(16,185,129,0.10);border-color:rgba(16,185,129,0.35);}',
        '.badgeReleased{color:#06b6d4;background:rgba(6,182,212,0.10);border-color:rgba(6,182,212,0.35);}',
        '.badgeRecv{color:#ef4444;background:rgba(239,68,68,0.12);border-color:rgba(239,68,68,0.4);}',
        '.badgeBacklog{color:#EE8C3A;background:rgba(238,140,58,0.10);border-color:rgba(238,140,58,0.35);}',
        '.badgeLegacy{color:#64748b;background:rgba(100,116,139,0.12);border-color:rgba(100,116,139,0.35);}',
        '.badgePaused{color:#f59e0b;background:rgba(245,158,11,0.12);border-color:rgba(245,158,11,0.4);}',
        '',
        '/* FS-UNIFY v9 -- one-word badges, rounded bottoms, money contrast */',
        '',
        ".releaseBtn{display:inline-flex;align-items:center;gap:5px;height:clamp(32px,4vw,38px);padding:0 clamp(10px,1.3vw,15px);background:rgba(6,182,212,0.12);border:1.5px solid rgba(6,182,212,0.45);color:#06b6d4;border-radius:6px;font-family:'Inter',sans-serif;font-weight:900;font-size:var(--fs-btn);letter-spacing:1.5px;text-transform:uppercase;cursor:pointer;}",
        '.releaseBtn:hover:not(:disabled){background:#06b6d4;color:#1a2e30;}',
        '.releaseBtn:disabled:not(.releaseBtnDone){opacity:0.45;cursor:not-allowed;border-style:dashed;}',
        ".problemBtn{display:inline-flex;align-items:center;gap:5px;height:clamp(32px,4vw,38px);padding:0 clamp(10px,1.3vw,15px);background:rgba(239,68,68,0.08);border:1.5px solid rgba(239,68,68,0.35);color:#fca5a5;border-radius:6px;font-family:'Inter',sans-serif;font-weight:900;font-size:var(--fs-btn);letter-spacing:1.5px;text-transform:uppercase;cursor:pointer;}",
        '.problemBtnActive{background:#ef4444;color:#fff;border-color:#ef4444;}',
        '',
        '/* FS-UNIFY v10 -- comprehensive audit fixes */',
        '.capsBadge{background:none !important;border:none !important;color:rgba(255,255,255,0.35) !important;font-size:8px !important;font-weight:700 !important;letter-spacing:0.5px !important;padding:0 !important;}',
        '.hwPanel{border-radius:10px !important;}',
        '.panelBody{border-radius:0 0 10px 10px;}',
        '.statGreen strong{color:#10b981 !important;}',
        '.statRed strong{color:#ef4444 !important;}',
        '',
        '.badgeActive{color:#10b981;background:rgba(16,185,129,0.12);border-color:rgba(16,185,129,0.4);}',
        '.badgeCritical{color:#ef4444;background:rgba(239,68,68,0.12);border-color:rgba(239,68,68,0.4);}',
        '',
        '.badgeReleased{color:#06b6d4;background:rgba(6,182,212,0.12);border-color:rgba(6,182,212,0.4);}',
        '.badgeProblem{color:#ef4444;background:rgba(239,68,68,0.12);border-color:rgba(239,68,68,0.4);}',
        '',
        '/* FS-UNIFY v11 -- note contrast, grouped related projects, released state */',
        '',
        '.ownerRelGroup{margin-bottom:clamp(10px,1.3vw,14px);}',
        ".ownerRelName{font-family:'Cinzel',serif;color:#fff;font-size:clamp(11px,1.2vw,14px);letter-spacing:1px;margin:0 0 6px;border-bottom:1px solid rgba(255,255,255,0.12);padding-bottom:4px;}",
        '.releaseBtnDone{background:#10b981;border-color:#10b981;color:#fff;opacity:0.9;cursor:default;}',
        '.payReversed{margin-left:8px;padding:1px 6px;border-radius:4px;background:rgba(239,68,68,0.16);border:1px solid rgba(239,68,68,0.5);color:#fca5a5;font-size:9px;font-weight:900;letter-spacing:1px;}',
        '.reverseBtn{margin-top:6px;padding:3px 9px;border-radius:5px;background:transparent;border:1px solid rgba(239,68,68,0.45);color:#fca5a5;font-size:9px;font-weight:900;letter-spacing:1px;cursor:pointer;}',
        '.reverseBtn:hover{background:#ef4444;color:#fff;border-color:#ef4444;}',
        '.storageBlock{margin-bottom:clamp(8px,1vw,12px);padding:clamp(8px,1vw,12px);background:rgba(239,68,68,0.06);border:1px solid rgba(239,68,68,0.25);border-radius:8px;}',
        '',
        ".frozenChip{display:inline-flex;align-items:center;gap:5px;background:rgba(6,182,212,0.12);border:1px solid rgba(6,182,212,0.4);color:#06b6d4;border-radius:999px;padding:4px 12px;font-family:'Space Mono',monospace;font-size:11px;font-weight:700;}",
        '',
        '/* fix86: light-on-dark meta for recovery chips inside NOTES panel */',
        '',
        '/* fix112: middle-insert plus button + insert position line + print-safe tab wrapper */',
        '',
        '/* fix113: middle-insert plus button + insert position line + print-safe tab wrapper */',
        '',
        '.tabWrap { display: block; }',
        '@media print { .tabWrap { display: block !important; } }',
        '',
        '/* fix114: middle-insert plus button + insert position line */',
        '.plusBtn { background: transparent; border: 1px solid rgba(238,140,58,0.3); color: #EE8C3A; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; padding: 4px 6px; border-radius: 4px; transition: all 0.2s; font-size: 12px; flex-shrink: 0; }',
        '.plusBtn:hover { background: rgba(238,140,58,0.12); border-color: #EE8C3A; }',
        '.plusBtn:focus-visible { outline: 2px solid #EE8C3A; outline-offset: 1px; }',
        ".insertCtx { font-family: 'DM Sans', sans-serif; font-size: clamp(9px, 0.95vw, 11px); color: #EE8C3A; font-weight: 800; letter-spacing: 0.5px; text-transform: uppercase; }",
        '',
        '/* fix116: Intake-mirrored stage checklist rows */',
        '.stageList { display: flex; flex-direction: column; gap: 6px; }',
        '.stageItem { display: flex; align-items: center; gap: 10px; padding: 9px 12px; background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 7px; cursor: pointer; transition: border-color 0.2s; }',
        '.stageItem:hover { border-color: rgba(238,140,58,0.35); }',
        '.stageItemChecked { background: rgba(238,140,58,0.06); border-color: rgba(238,140,58,0.3); }',
        '.stageItemChecked .stageItemName { text-decoration: line-through; color: var(--fs-muted); }',
        '.stageCheckbox { width: 15px; height: 15px; accent-color: #EE8C3A; cursor: pointer; flex-shrink: 0; }',
        '.stageItemName { font-weight: 700; color: #fff; font-size: clamp(11px, 1.1vw, 13px); letter-spacing: 0.5px; flex: 1; min-width: 0; }',
        '.stageActions { margin-left: auto; display: flex; gap: 8px; align-items: center; }',
        '.insertRow { display: flex; align-items: center; gap: 8px; padding: 8px 12px; border: 1px dashed rgba(238,140,58,0.45); border-radius: 7px; background: rgba(238,140,58,0.05); flex-wrap: wrap; }',
        ".insertInput { flex: 1; min-width: 140px; background: rgba(0,0,0,0.25); border: 1px solid rgba(255,255,255,0.15); border-radius: 5px; color: #fff; padding: 7px 9px; font-family: 'DM Sans', sans-serif; font-size: 12px; }",
        '.insertInput:focus { outline: none; border-color: #EE8C3A; }',
        '',
        '/* fix117: Intake/Recovery button tones + panel heading glow + header-aware scroll-top */',
        '.drawerTitle { text-shadow: 0 0 12px rgba(238,140,58,0.45); }',
        '',
        '.plusBtn { background: transparent; border: 1px solid var(--orange-border, rgba(238,140,58,0.28)); color: var(--fs-orange, #EE8C3A); width: clamp(24px,2.8vw,30px); height: clamp(24px,2.8vw,30px); border-radius: var(--radius-sm,6px); display: inline-flex; align-items: center; justify-content: center; cursor: pointer; transition: background .2s, color .2s, border-color .2s; font-size: 12px; flex-shrink: 0; }',
        '.plusBtn:hover { background: var(--fs-orange, #EE8C3A); color: #1a2e30; border-color: var(--fs-orange, #EE8C3A); }',
        '.iconBtnDanger { background: transparent; border: none; color: var(--fs-red, #ef4444); width: clamp(24px,2.8vw,30px); height: clamp(24px,2.8vw,30px); border-radius: var(--radius-sm,6px); display: inline-flex; align-items: center; justify-content: center; cursor: pointer; transition: background .2s; font-size: 13px; flex-shrink: 0; }',
        '.iconBtnDanger:hover { background: rgba(239,68,68,0.14); }',
        '.stageListTop { display: flex; justify-content: flex-end; margin-bottom: 2px; }',
        '.scrollTopBtn { position: fixed; right: clamp(14px,2vw,24px); bottom: clamp(14px,2vw,24px); z-index: 400; width: clamp(38px,4.5vw,46px); height: clamp(38px,4.5vw,46px); border-radius: 50%; background: #EE8C3A; color: #1a2e30; border: none; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 18px; box-shadow: 0 3px 14px rgba(238,140,58,0.45); transition: background .2s, transform .2s; }',
        '.scrollTopBtn:hover { background: #f0a050; transform: translateY(-2px); }',
        '.scrollTopBtn:focus-visible { outline: 2px solid #EE8C3A; outline-offset: 2px; }',
        '',
        '/* \u2500\u2500 OWNER NAME LINK (fix69) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500',
        '   Matches .ownerName exactly, plus the affordances that say it goes',
        '   somewhere: pointer, underline on hover, a real focus ring. It is a',
        '   <button> and not an <a> because it navigates through the router. */',
        '.ownerNameLink {',
        '  display: block; width: 100%; text-align: left;',
        '  background: none; border: none; padding: 0; margin: 0 0 10px;',
        "  font-family: 'Cinzel', serif;",
        '  font-size: clamp(14px, 1.6vw, 19px);',
        '  font-weight: 700; letter-spacing: 1px; text-transform: uppercase;',
        '  color: #EE8C3A; cursor: pointer;',
        '  transition: color 0.15s, text-decoration-color 0.15s;',
        '  text-decoration: underline; text-decoration-color: rgba(238, 140, 58, 0.35);',
        '  text-underline-offset: 4px;',
        '}',
        '.ownerNameLink:hover { color: #fff; text-decoration-color: #fff; }',
        '.ownerNameLink:focus-visible { outline: 2px solid #EE8C3A; outline-offset: 3px; border-radius: 3px; }',
        '',
        '/* fix136: document category headings + the UPLOAD DOCUMENTS window */',
        ".docGroupLabel{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:clamp(4px,0.6vw,8px);padding:0 2px;font-family:'Space Mono',monospace;font-weight:900;font-size:clamp(8px,0.85vw,10px);letter-spacing:1.5px;text-transform:uppercase;color:var(--orange);}",
        '.docGroupLabel:first-child{margin-top:0;}',
        '.docGroupCount{color:rgba(255,255,255,0.35);}',
        '.upFileList{display:flex;flex-direction:column;gap:6px;max-height:clamp(140px,30vh,260px);overflow-y:auto;margin-bottom:8px;}',
        '.upFileRow{display:flex;align-items:center;gap:8px;min-width:0;}',
        '.upFileName{flex:1 1 50%;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:rgba(255,255,255,0.8);font-size:12px;}',
        '.upFileSelect{flex:1 1 50%;min-width:0;}',
        '.upCatActions{display:flex;gap:8px;}',
        '.upCatActions .addDocBtn{flex:1;}',
        '',
        '/* fix138: payment receipt field (RECORD PAYMENT window) + PROBLEM window */',
        '.recFile{display:flex;align-items:center;gap:8px;min-width:0;margin-top:clamp(5px,0.6vw,7px);padding:clamp(8px,1vw,11px) clamp(10px,1.3vw,14px);background:rgba(34,197,94,0.08);border:1px solid rgba(34,197,94,0.28);border-radius:6px;color:rgba(255,255,255,0.9);font-size:clamp(11px,1.05vw,13px);font-weight:700;}',
        '.recFile svg{flex-shrink:0;color:#22c55e;}',
        '.recName{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}',
        '.recRemove{flex-shrink:0;display:inline-flex;align-items:center;justify-content:center;width:24px;height:24px;background:transparent;border:1.5px solid rgba(255,255,255,0.18);border-radius:6px;color:rgba(255,255,255,0.7);cursor:pointer;transition:background 0.2s,border-color 0.2s,color 0.2s;}',
        '.recRemove:hover{background:rgba(239,68,68,0.15);border-color:#ef4444;color:#ef4444;}',
        '.recRemove:focus-visible{outline:2px solid var(--orange);outline-offset:2px;}',
        '.recHint{display:block;margin-top:6px;font-size:clamp(9px,0.9vw,11px);font-weight:700;letter-spacing:0.5px;color:rgba(255,255,255,0.45);}',
        ".probCount{display:block;margin-top:5px;text-align:right;font-family:'Space Mono',monospace;font-size:clamp(9px,0.9vw,11px);font-weight:700;color:rgba(255,255,255,0.4);}",
        '.probBox{min-height:clamp(96px,16vh,140px);resize:vertical;}',
        '',
        '/* =====================================================================',
        '   fix167 -- folder page review pass',
        '   ===================================================================== */',
        '/* RED errors are red (popup box, field message, field label) */',
        '.modalErr { background: rgba(239, 68, 68, 0.12); border: 1.5px solid #ef4444; color: #f87171; font-weight: 800; }',
        '.modalErrIcon { color: #ef4444; }',
        '.fieldError { color: #f87171; }',
        '.inputError .inputLabelRow label { color: #f87171; }',
        '.probCountOver { color: #f87171; }',
        '',
        '/* confirm button for danger confirms (popup standard size, red) */',
        ".modalDangerBtn { display: inline-flex; align-items: center; gap: clamp(6px, 0.8vw, 9px); height: var(--btn-height, clamp(32px, 4vw, 38px)); padding: 0 clamp(10px, 1.4vw, 16px); background: #ef4444; color: #fff; border: none; border-radius: 6px; font-family: 'Inter', sans-serif; font-weight: 900; font-size: var(--btn-font, clamp(8px, 0.85vw, 10px)); letter-spacing: 1.5px; text-transform: uppercase; cursor: pointer; transition: background 0.2s, box-shadow 0.2s; }",
        '.modalDangerBtn:hover { background: #dc2626; box-shadow: 0 0 16px rgba(239, 68, 68, 0.35); }',
        '',
        '/* FLAG PROBLEM readable on the cream header (it looked disabled) */',
        '.problemBtn { background: rgba(239, 68, 68, 0.1); border: 1.5px solid #ef4444; color: #b91c1c; transition: background 0.2s, color 0.2s; }',
        '.problemBtn:hover { background: #ef4444; color: #fff; }',
        '.problemBtnActive, .problemBtnActive:hover { background: #ef4444; color: #fff; border-color: #ef4444; }',
        '',
        '/* stage ticks: orange in view mode too (no greyed disabled box), read-only rows do not look clickable */',
        '.stageItemRO { cursor: default; }',
        '.stageItemRO:hover { border-color: rgba(255, 255, 255, 0.08); }',
        '.stageItemRO.stageItemChecked:hover { border-color: rgba(238, 140, 58, 0.3); }',
        '.stageItemRO .stageCheckbox { pointer-events: none; cursor: default; }',
        ".stageMeta { font-family: 'Space Mono', monospace; font-size: clamp(8px, 0.85vw, 10px); font-weight: 700; color: rgba(255, 255, 255, 0.45); white-space: nowrap; }",
        ".stageProgress { font-family: 'DM Sans', sans-serif; font-weight: 900; font-size: clamp(8px, 0.85vw, 10px); letter-spacing: 1.5px; color: #EE8C3A; margin-right: auto; }",
        '.stageListTop { display: flex; align-items: center; justify-content: flex-end; gap: 10px; flex-wrap: wrap; margin-bottom: 2px; }',
