# old backup copies nobody uses (removed only when every patch above matched)
if not MISSING:
    _bak = os.path.join(ROOT, 'erp-frontend', 'src', 'pages', 'DigitalFolder', 'FolderPage.jsx.bak')
    if os.path.exists(_bak):
        os.remove(_bak)
        print("deleted: erp-frontend/src/pages/DigitalFolder/FolderPage.jsx.bak")
    else:
        print("SKIP: erp-frontend/src/pages/DigitalFolder/FolderPage.jsx.bak already gone")
    _bak = os.path.join(ROOT, 'erp-frontend', 'src', 'pages', 'Intake', 'IntakePage.jsx.bak')
    if os.path.exists(_bak):
        os.remove(_bak)
        print("deleted: erp-frontend/src/pages/Intake/IntakePage.jsx.bak")
    else:
        print("SKIP: erp-frontend/src/pages/Intake/IntakePage.jsx.bak already gone")
